// x509-parse-chain, Zig, idiomatic std: std.crypto.Certificate.parse over
// the input of mk/x509-parse-chain.mk's comment (the same three DER
// certificates, decoded from hex at run time), the same checksum. Zig's
// parse reads less than std.x509's and Go's (it validates no extension
// but the subjectAltName's place, and leaves the key unparsed).
const std = @import("std");
const Certificate = std.crypto.Certificate;

const leaf_hex = "";
const inter_hex = "";
const root_hex = "";

pub fn main(init: std.process.Init) !void {
    const gpa = init.arena.allocator();
    const args = try init.minimal.args.toSlice(gpa);
    if (args.len != 2) return error.Usage;
    const reps = try std.fmt.parseInt(u64, args[1], 10);
    const hexes = [_][]const u8{ leaf_hex, inter_hex, root_hex };
    var ders: [3][]u8 = undefined;
    for (hexes, 0..) |h, i| {
        ders[i] = try gpa.alloc(u8, h.len / 2);
        _ = try std.fmt.hexToBytes(ders[i], h);
    }
    var sum: u64 = 0;
    var i: u64 = 0;
    while (i < reps) : (i += 1) {
        for (ders) |d| {
            const p = try (Certificate{ .buffer = d, .index = 0 }).parse();
            sum += (p.validity.not_before + p.validity.not_after) % 1000;
        }
    }
    var out: [64]u8 = undefined;
    var w = std.Io.File.stdout().writer(init.io, &out);
    try w.interface.print("{d}\n", .{sum});
    try w.interface.flush();
}
